import java.io.*;
import java.util.*;

public class Main {
    static FastReader in;
    static PrintWriter out;
    static final int MOD = 998244353;
    static long even, odd;
    static HashMap<Long, long[]> pairMemo = new HashMap<>();

    static long pow(long a, long b) {
        long res = 1;
        while (b != 0) {
            if ((b & 1) != 0) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            b >>= 1;
        }
        return res;
    }

    static long[] getPair(long n) {
        long[] cached = pairMemo.get(n);
        if (cached != null) {
            return cached;
        }

        long[] ans;
        if (n == 1) {
            ans = new long[] { even, odd };
        } else if (n == 2) {
            ans = new long[] {
                (even * even + odd * odd) % MOD,
                (even * odd + odd * even) % MOD
            };
        } else {
            long[] left = getPair(n / 2);
            long[] right = getPair(n - n / 2);
            ans = new long[] {
                (left[0] * right[0] + left[1] * right[1]) % MOD,
                (left[0] * right[1] + left[1] * right[0]) % MOD
            };
        }

        pairMemo.put(n, ans);
        return ans;
    }

    static void solve() {
        long n = in.nextInt();
        long m = in.nextInt();
        long l = in.nextInt();
        long r = in.nextInt();
        long sz = n * m;

        if (sz % 2 == 0) {
            even = (r - l + 1) / 2;
            if ((r - l) % 2 == 0 && l % 2 == 0) {
                even++;
            }
            odd = r - l + 1 - even;
            out.println(getPair(sz)[0]);
        } else {
            out.println(pow(r - l + 1, sz));
        }
    }

    public static void main(String[] args) {
        in = new FastReader(System.in);
        out = new PrintWriter(System.out);
        int tests = 1;
        while (tests-- > 0) {
            solve();
        }
        out.close();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        Integer nextInt() {
            return Integer.parseInt(next());
        }

        Long nextLong() {
            return Long.parseLong(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        String nextLine() {
            String s = "";
            try {
                s = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return s;
        }
    }
}
